import { Parser, ReplacementRules, popKeys, isDict } from './parser';
import { Generators, createPromptInfo, createSampler, createModel, PromptInfo, Model } from '../data';
import { ParserError } from '../exceptions';
import { readJsonObject, take, promptList } from './helpers';

const SAMPLER_PARAMS = ['seed', 'steps', 'cfgscale', 'scheduler', 'denoising_strength'];
const REPLACEMENT_RULES: ReplacementRules = [['cfgscale', 'cfg_scale']];

/**
 * Parser for images generated by SwarmUI
 *
 * SwarmUI writes a `sui_image_params` JSON object to the PNG `parameters` chunk or the EXIF UserComment.
 */
export class SwarmUIParser extends Parser {
  public readonly generator = Generators.SWARMUI;

  async parse(parameters: Record<string, any>): Promise<PromptInfo> {
    const source = [parameters.parameters, parameters.UserComment].find(
      value => typeof value === 'string' && value.includes('sui_image_params')
    );
    if (!source) {
      throw new ParserError('no SwarmUI parameters found');
    }
    const data = readJsonObject(source);
    if (!isDict(data.sui_image_params)) {
      throw new ParserError('no SwarmUI parameters found');
    }

    const params: Record<string, any> = { ...data.sui_image_params };
    const samplerName = take(params, 'sampler') ?? 'unknown';
    const prompt = take(params, 'prompt');
    const negativePrompt = take(params, 'negativeprompt');
    const modelName = take(params, 'model');

    const models: any[] = Array.isArray(data.sui_models) ? data.sui_models : [];
    const modelInfo = models.find(entry => isDict(entry) && entry.param === 'model');
    let model: Model | undefined;
    if (modelName || modelInfo?.name) {
      model = createModel({ name: modelName ?? modelInfo.name, hash: modelInfo?.hash });
    }

    const sampler = createSampler(samplerName, this.normalizeParameters(popKeys(SAMPLER_PARAMS, params), REPLACEMENT_RULES), {
      model,
      prompts: promptList(prompt),
      negativePrompts: promptList(negativePrompt),
    });

    const metadata: Record<string, any> = { ...params };
    if (isDict(data.sui_extra_data)) metadata.sui_extra_data = data.sui_extra_data;
    if (models.length > 0) metadata.sui_models = models;

    return createPromptInfo(this.generator, [sampler], metadata, parameters);
  }
}
